// src/schemas/item.schema.js
// Validation schemas for Item endpoints. The `code` field is generated by the backend,
// so it is not required (or even allowed) in the request payload.

module.exports = {
  // List items – optional query filters
  listItemSchema: {
    type: "object",
    additionalProperties: false,
    properties: {
      category_code: { type: "string" },
      search: { type: "string" },
      skip: { type: "integer", minimum: 0 },
      take: { type: "integer", minimum: 1 },
    },
  },

  // Create item payload – client does NOT send `code`.
  createItemSchema: {
    type: "object",
    required: ["name", "itemCategoryCode", "uom"], // brandCode optional, defaults to "000"
    additionalProperties: false,
    properties: {
      name: { type: "string" },
      itemCategoryCode: { type: "string" },
      brandCode: { type: "string", default: "000" },
      uom: { type: "string" },
      stock: { type: "number", minimum: 0 },
    },
  },

  // Update item payload (partial)
  updateItemSchema: {
    type: "object",
    minProperties: 1,
    additionalProperties: false,
    properties: {
      name: { type: "string" },
      brandCode: { type: "string" },
      uom: { type: "string" },
      stock: { type: "number", minimum: 0 },
    },
  },
};
